INSERT INTO `faq_table` (`faq_question`, `faq_answer`, `status`, `sort`, `category_id`, `id`) VALUES
('Do you provide custom-sized FRP planters?', '<p>Absolutely! As a manufacturer, Yuccabe Planters offers fully customised FRP planters based on your specific dimensions, shape, colour, and finish requirements. Simply share your design and we&#39;ll manufacture it for you.</p>\r\n', 1, 1, 1, 2),
('Are FRP planters suitable for indoor use?', '<p>Yes, FRP planters are perfect for indoor environments. They are moisture-resistant, do not rust or crack, and are available in elegant finishes that complement any interior d&eacute;cor &mdash; from homes and offices to hotels and malls.</p>\r\n', 1, 2, 1, 3),
('What is an FRP planter?', '<p>FRP planter is a plant pot or container made from Fibre Reinforced Plastic (FRP), also known as fibreglass. FRP planters are lightweight, durable, weather-resistant, and available in a variety of shapes, sizes, and finishes &mdash; making them ideal for indoor and decorative use.</p>\r\n', 1, 3, 1, 4),
('How long do FRP planters last?', '<p>FRP planters are highly durable and can last 10&ndash;15 years or more with normal use. They are resistant to UV rays, moisture, temperature changes, and physical impacts, making them a long-term investment compared to ceramic or terracotta planters.</p>\r\n', 1, 0, 1, 5),
('Do you supply FRP planters across all of India?', '<p>Yes, Yuccabe Planters provides pan-India delivery of FRP planters. We ship to all major cities and states, including Mumbai, Delhi, Bangalore, Hyderabad, Chennai, Kolkata, Pune, Ahmedabad, and beyond.</p>\r\n', 1, 0, 1, 6),
(' Can I order FRP planters in bulk?', '<p>Yes, we accept bulk orders and provide special pricing for large-volume purchases. We supply to hotels, builders, corporate offices, malls, and landscaping companies. Contact us to discuss your bulk requirements and get the best quote.</p>\r\n', 1, 0, 1, 7),
('How are FRP planters different from plastic or ceramic planters?', '<p>FRP planters are superior to ordinary plastic planters in strength, finish quality, and longevity. Compared to ceramic planters, FRP planters are far lighter and less fragile, making them easier to handle and transport. FRP also allows for far greater design flexibility.</p>\r\n', 1, 0, 1, 8),
('Are your ceramic pots suitable for outdoor use?', '<p>Yes! Our outdoor ceramic planters are specially high-fired and glazed to withstand Indian weather conditions, including heat, rain, and humidity. However, we recommend bringing delicate hand-painted ceramic pots indoors during heavy monsoon rains.</p>\r\n', 1, 0, 2, 9),
('Do you offer custom designs and sizes?', '<p>Absolutely! As experienced ceramic pot manufacturers, we accept custom orders for specific shapes, sizes, colours, finishes, and even logo/brand printing on the pots. Contact our team with your requirements.</p>\r\n', 1, 0, 2, 10),
('What is the minimum order quantity for bulk orders?', '<p>MOQ varies based on the product type and customization required. For standard designs, we accept smaller quantities as well. For bulk wholesale pricing, please contact our sales team directly.</p>\r\n', 1, 0, 2, 11),
('Do you deliver across India?', '<p>Yes, we offer pan-India delivery with proper secure packaging to ensure your ceramic pots arrive safely. We deliver to Delhi, Mumbai, Bangalore, Hyderabad, Chennai, Pune, Ahmedabad, and all other major cities.</p>\r\n', 1, 0, 2, 12),
('What is the difference between ceramic and terracotta pots?', '<p>Terracotta is unglazed fired clay, while ceramic pots are kiln-fired at higher temperatures and usually have a glaze coating. Ceramic pots are more durable, less porous, and available in many more colours and finishes than terracotta.</p>\r\n', 1, 0, 2, 13);

