INSERT INTO `posts` (`id`, `title`, `bread_heading`, `slug`, `content`, `image`, `alt`, `metatag`, `metadescription`, `metakeywords`, `head_tags`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Why FRP Planters Are the Best Choice for Commercial Spaces', 'Why FRP Planters Are the Best', 'why-frp-planters-are-the-best-choice-for-commercial-spaces', '<p><span style=\"color:#000000\"><span style=\"font-size:16px\">When it comes to decorating commercial spaces &mdash; hotels, offices, malls, airports, hospitals, or residential complexes &mdash; the choice of planters plays a major role in defining the aesthetic and ambiance of the space. Among all the options available today, FRP planters (Fibre Reinforced Plastic planters) have emerged as the number one choice for commercial spaces across India and globally.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">But what makes FRP planters so special? Why are architects, interior designers, and facility managers increasingly turning to FRP planter manufacturers for their projects? In this blog, we&#39;ll answer all these questions and more.</span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"color:#000000\"><strong>What Are FRP Planters?</strong></span></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">FRP stands for Fibre Reinforced Plastic &mdash; a composite material made from a polymer matrix reinforced with fibres, usually glass fibres. FRP planters are moulded from this material to create lightweight, durable, and highly customizable plant containers.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Unlike traditional concrete, terracotta, or ceramic planters, FRP planters are manufactured using advanced moulding techniques that allow for virtually any shape, size, colour, or finish &mdash; making them a top pick for both outdoor FRP planters manufacturers and indoor d&eacute;cor specialists.</span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"color:#000000\"><strong>Top Reasons Why FRP Planters Are Ideal for Commercial Spaces</strong></span></h2>\r\n\r\n<h3><span style=\"color:#000000\"><strong>1. Exceptional Durability</strong></span></h3>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Commercial spaces experience heavy footfall, outdoor weather exposure, and constant use. FRP planters are engineered to withstand all of this:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Resistant to UV rays, heat, and extreme weather conditions</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Do not crack, chip, or fade easily like ceramic or terracotta pots</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Corrosion-resistant &mdash; ideal for coastal or humid environments</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Long service life of 10&ndash;15+ years with minimal maintenance</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><em>This makes FRP planters a cost-effective long-term investment compared to other materials.</em></span></span></p>\r\n\r\n<h3><span style=\"color:#000000\"><strong>2. Lightweight Yet Strong</strong></span></h3>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">One of the biggest challenges in commercial spaces &mdash; especially high-rise buildings, rooftop gardens, and elevated terraces &mdash; is managing the weight load. Heavy concrete or stone planters can put serious structural strain on the building.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">FRP planters solve this problem brilliantly. Despite being extremely lightweight (up to 70% lighter than concrete), they are structurally strong and can hold large plants and trees with ease. This is why outdoor FRP planter manufacturers are in high demand for terrace gardens, hotel lobbies, and commercial landscapes.</span></span></p>\r\n\r\n<h3><span style=\"color:#000000\"><strong>3. Fully Customizable Design</strong></span></h3>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Commercial spaces demand unique aesthetics that match their branding and design language. This is where FRP planters truly shine. As a leading customized FRP planters manufacturer, Yuccabe Planters offers:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Any shape &mdash; round, square, rectangular, oval, hexagonal, or custom silhouettes</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Any size &mdash; from small tabletop planters to large floor planters over 6 feet</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Any finish &mdash; matte, glossy, textured, metallic, stone-look, wood-look</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Any colour &mdash; matched to brand colours, Pantone codes, or RAL colours</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Custom logo embossing or branding on the planter surface</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">This level of customization is simply not possible with ceramic, GRC, or concrete planters at the same price point.</span></span></p>\r\n\r\n<h3><span style=\"color:#000000\"><strong>4. Weather &amp; Water Resistant</strong></span></h3>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Commercial outdoor spaces face harsh Indian weather &mdash; blazing summers, monsoon rains, and cold winters. FRP planters are non-porous, meaning water does not seep into the material. This prevents:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Moss or algae growth on the surface</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Cracking due to freeze-thaw cycles</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Staining from water or soil minerals</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Rusting (unlike metal planters)</span></span></li>\r\n</ul>\r\n\r\n<h3><span style=\"color:#000000\"><strong>5. Easy to Transport and Install</strong></span></h3>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Whether you are decorating a new hotel property, renovating a mall, or setting up a corporate office landscape, speed and ease of installation matter. FRP planters are easy to move, reposition, and install without heavy machinery or labour costs &mdash; significantly reducing project timelines.</span></span></p>\r\n\r\n<h3><span style=\"color:#000000\"><strong>6. Low Maintenance</strong></span></h3>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">In commercial spaces, maintenance is a huge cost factor. FRP planters require virtually zero maintenance compared to other materials. A simple wipe-down with a wet cloth keeps them looking brand new. There is no need for painting, sealing, or special treatments.</span></span></p>\r\n\r\n<h3><span style=\"color:#000000\"><strong>7. Eco-Friendly and Sustainable</strong></span></h3>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Modern businesses are increasingly focused on sustainability. FRP planters support this goal because:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Their long lifespan reduces the need for frequent replacement</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Lightweight nature reduces carbon emissions during transport</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Can be manufactured using recycled glass fibres</span></span></li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"color:#000000\"><strong>Best Commercial Applications for FRP Planters</strong></span></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hotels &amp; Resorts &mdash; Lobby entrances, poolside, restaurants, rooftop gardens</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Shopping Malls &mdash; Atriums, food courts, entranceways, parking areas</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Corporate Offices &mdash; Reception areas, terraces, co-working spaces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hospitals &amp; Healthcare Facilities &mdash; Healing gardens, corridors, outdoor areas</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Airports &amp; Metro Stations &mdash; Large public spaces requiring durable, attractive planters</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Residential Complexes &mdash; Clubhouse, garden areas, podium landscapes</span></span></li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"color:#000000\"><strong>Why Choose Yuccabe Planters as Your FRP Planter Manufacturer?</strong></span></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>At Yuccabe Planters, we are one of India&#39;s most trusted FRP planter manufacturers and outdoor FRP planter suppliers. Here&#39;s what sets us apart:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Wide catalogue &mdash; Over 500+ designs in FRP, GRC, ceramic, and plastic planters</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Custom manufacturing &mdash; We build to your specifications, shape, colour, and size</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Bulk orders &mdash; Competitive pricing for large commercial and infrastructure projects</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Pan-India delivery &mdash; We ship to all major cities across India</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Expert guidance &mdash; Our team helps you select the right planter for your space and budget</span></span></li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"color:#000000\"><strong>Conclusion</strong></span></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">FRP planters are not just a trend &mdash; they are a smart, long-term investment for any commercial space. Their combination of durability, lightweight design, full customization, weather resistance, and low maintenance make them the undisputed champion in the world of commercial planters.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Whether you are an architect planning a luxury hotel landscape, a facility manager of a corporate campus, or a developer designing a residential complex &mdash; FRP planters from Yuccabe are your best choice.</span></span></p>', 'blogs/1770276289.jpg', 'Why FRP Planters Are the Best', 'Why FRP Planters Are the Best Choice for Commercial Spaces', 'Looking for durable and stylish planters for hotels, offices & malls? Discover why FRP planters are the #1 choice for commercial spaces. Get custom FRP planters from Yuccabe Planters.', 'Why FRP Planters Are the Best, FRP Planters for Commercial Spaces', NULL, 74, 1, '2026-02-05 01:47:19', '2026-03-27 13:05:14');
INSERT INTO `posts` (`id`, `title`, `bread_heading`, `slug`, `content`, `image`, `alt`, `metatag`, `metadescription`, `metakeywords`, `head_tags`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(2, 'What Are GRC Planters and Why Are Architects Loving Them?', 'GRC Planters', 'what-are-grc-planters-why-architects-love-them', '<p><span style=\"font-size:16px\">Walk into any modern hotel lobby, luxury residential complex, or award-winning commercial space in India today &mdash; and chances are you will notice them. Large, bold, strikingly designed planters that look like concrete but feel impossibly refined. Clean lines, dramatic textures, monumental presence &mdash; yet placed effortlessly in elevated terraces and rooftop gardens without any structural concerns.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Those are GRC planters. And they are quickly becoming the material of choice for architects, landscape designers, and urban developers across the country.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">So what exactly are GRC planters? What makes them so special? And why is every serious architect talking about them? Read on &mdash; this blog answers everything.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><strong>What Are GRC Planters?</strong></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\">GRC stands for Glass Fibre Reinforced Concrete &mdash; a composite material made by combining Portland cement, fine aggregates, water, and alkali-resistant (AR) glass fibres. The result is a material that has all the aesthetic appeal of traditional concrete but is significantly lighter, stronger, and far more versatile in terms of design.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">GRC planters are plant containers manufactured using this composite material. They are typically produced using spray-up or premix casting techniques that allow them to be moulded into virtually any shape, size, and surface texture &mdash; from smooth and polished to rough and stone-like.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">In simple terms: GRC planters look and feel like premium concrete or stone &mdash; but they are much lighter, much stronger, and far more design-flexible.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><strong>How Are GRC Planters Made?</strong></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\">The manufacturing process is what sets GRC apart from regular concrete. At Yuccabe Planters, our GRC manufacturing process follows these key steps:</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Step 1 &mdash; Mould Preparation</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Custom moulds are created based on the design specifications &mdash; shape, size, surface texture, and detailing. These moulds can be made from GRP, timber, or foam, giving total creative freedom.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Step 2 &mdash; Spray-Up or Premix Application</span></p>\r\n\r\n<p><span style=\"font-size:16px\">The GRC mix &mdash; a blend of cement, fine sand, water, admixtures, and AR glass fibres &mdash; is either sprayed into the mould in layers (spray-up method) or poured as a premix. This is what gives GRC its incredible strength-to-weight ratio.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Step 3 &mdash; Curing</span></p>\r\n\r\n<p><span style=\"font-size:16px\">The moulded piece is allowed to cure under controlled conditions to achieve full strength. The curing process is carefully monitored to ensure dimensional stability and surface quality.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Step 4 &mdash; Demoulding &amp; Finishing</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Once cured, the planter is demoulded, inspected, and finished. Surface treatments &mdash; painting, texturing, acid washing, sandblasting, or pigment colouring &mdash; are applied to achieve the desired look.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Step 5 &mdash; Quality Check &amp; Dispatch</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Each GRC planter undergoes a thorough quality check before packaging and dispatch. This ensures structural integrity, surface quality, and dimensional accuracy in every piece.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><strong>Why Are Architects Falling in Love with GRC Planters?</strong></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>This is the big question &mdash; and the answer lies in the unique combination of properties that GRC offers, which no other material can match at the same price point. Here are the top reasons architects and designers across India are specifying GRC planters in their projects:</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>1. Unmatched Design Freedom</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Architecture is about pushing boundaries. GRC allows architects to do exactly that when it comes to planters and landscape elements. Because GRC can be cast into any mould, the design possibilities are virtually limitless:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Any shape &mdash; rectangular, circular, organic, sculptural, or completely bespoke</span></li>\r\n	<li><span style=\"font-size:16px\">Any size &mdash; from small tabletop accents to massive 10-foot landmark planters</span></li>\r\n	<li><span style=\"font-size:16px\">Any surface texture &mdash; smooth, bush-hammered, exposed aggregate, ribbed, stone-look, wood-look</span></li>\r\n	<li><span style=\"font-size:16px\">Any colour &mdash; natural grey, white, black, earth tones, or custom pigments</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">This makes GRC the go-to material when architects need something that stands out &mdash; a planter that is not just a container for plants but a design statement in itself.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>2. Lightweight Without Sacrificing Strength</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>This is arguably the most important reason architects love GRC. Traditional concrete planters of the same size would be prohibitively heavy &mdash; making them impractical for rooftops, elevated podiums, suspended gardens, and high-rise terraces.</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>GRC planters are typically 75% lighter than equivalent solid concrete planters &mdash; yet they are structurally strong enough to hold large trees and dense soil mixes. This opens up landscaping possibilities that were previously impossible with traditional materials.</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Safe for rooftop gardens and terraces with load restrictions</span></li>\r\n	<li><span style=\"font-size:16px\">Easy to install without heavy machinery or large labour crews</span></li>\r\n	<li><span style=\"font-size:16px\">Can be relocated or repositioned as the design evolves</span></li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>3. Exceptional Durability and Longevity</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Architects think in decades, not years. GRC planters are built to last:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Highly resistant to UV radiation, preventing colour fading</span></li>\r\n	<li><span style=\"font-size:16px\">Weatherproof &mdash; unaffected by rain, heat, humidity, or frost</span></li>\r\n	<li><span style=\"font-size:16px\">Resistant to cracking, chipping, and surface degradation</span></li>\r\n	<li><span style=\"font-size:16px\">Non-porous surface does not absorb water, preventing moss, algae, or staining</span></li>\r\n	<li><span style=\"font-size:16px\">Typical service life of 20&ndash;30 years with minimal maintenance</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">When architects specify materials for a project, durability is paramount. GRC delivers the longevity of concrete without the weight or maintenance issues.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>4. Precision and Repeatability</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Large commercial and residential projects often require dozens &mdash; sometimes hundreds &mdash; of identical planters across a development. GRC manufacturing allows for precise, repeatable production from the same mould, ensuring every planter is dimensionally consistent and visually identical.</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>This is critical for architects who want uniformity across a large-scale landscape &mdash; something that handmade or natural materials simply cannot guarantee.</strong></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>5. Sustainability and Eco-Friendliness</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Sustainability is no longer optional in modern architecture &mdash; it is a core design requirement. GRC supports green building goals in several important ways:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Lower cement content than traditional concrete &mdash; reducing embodied carbon</span></li>\r\n	<li><span style=\"font-size:16px\">Long lifespan means reduced replacement cycles and less material waste</span></li>\r\n	<li><span style=\"font-size:16px\">Lightweight nature reduces transportation carbon footprint</span></li>\r\n	<li><span style=\"font-size:16px\">Compatible with rainwater harvesting and drainage management systems</span></li>\r\n	<li><span style=\"font-size:16px\">Can be manufactured using recycled glass fibres</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">Many GRC planter projects have contributed to green building ratings under LEED and IGBC certification schemes.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>6. Low Maintenance &mdash; Perfect for Commercial Projects</strong></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\">Facility managers of large commercial properties appreciate GRC planters for their near-zero maintenance requirements. Unlike painted metal that rusts, wood that rots, or ceramic that chips &mdash; GRC planters simply stay beautiful with occasional cleaning. No repainting, no sealing, no special treatments required.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>7. Seamless Integration with Architecture</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">GRC planters can be designed to match or complement the architectural language of the building itself &mdash; using the same colour palette, surface textures, and material finishes. This creates a sense of cohesion between the built environment and the landscape that elevates the entire project.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Many leading architects now use GRC planters as integrated landscape furniture &mdash; not just as plant holders, but as seat walls, room dividers, water features, and architectural focal points.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><strong>GRC Planters vs Other Materials &mdash; A Comparison</strong></h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<table cellspacing=\"0\" style=\"border-collapse:collapse\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"background-color:#cdc1bc; border-bottom:1.0px solid #cdc1bc; border-left:1.0px solid #cdc1bc; border-right:1.0px solid #cdc1bc; border-top:1.0px solid #cdc1bc; height:11.0px; vertical-align:middle; width:108.0px\">\r\n			<p><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:medium\"><span style=\"color:#2f1d1a\"><strong>Feature</strong></span></span></span></p>\r\n			</td>\r\n			<td style=\"background-color:#cdc1bc; border-bottom:1.0px solid #cdc1bc; border-left:1.0px solid #cdc1bc; border-right:1.0px solid #cdc1bc; border-top:1.0px solid #cdc1bc; height:11.0px; vertical-align:middle; width:79.0px\">\r\n			<p><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font