CREATE TABLE `projects` (
  `id` int(11) NOT NULL,
  `image` varchar(500) DEFAULT NULL,
  `name1` varchar(500) DEFAULT NULL,
  `slug` varchar(300) DEFAULT NULL,
  `name2` varchar(500) DEFAULT NULL,
  `content` text DEFAULT NULL,
  `status` tinyint(4) DEFAULT 1,
  `sort` tinyint(4) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `projects`
--

INSERT INTO `projects` (`id`, `image`, `name1`, `slug`, `name2`, `content`, `status`, `sort`) VALUES
(4, 'projects/1779426461_parliament.jpg,projects/1779426461_yu1.jpg,projects/1779426461_yu2.jpg,projects/1779426461_yu3.jpg', 'India Parliament', 'india-parliament', 'Greens of Governance', '<h4>Parliament of India</h4>\r\n\r\n<p>Completion Year</p>\r\n\r\n<h4>2024</h4>\r\n\r\n<p>Location</p>\r\n\r\n<h4>New Delhi, India</h4>\r\n\r\n<p>The New Parliament Building in New Delhi, part of the Central Vista redevelopment project, represents a monumental step forward in India&rsquo;s democratic and architectural vision. Designed with a focus on indigenous design, sustainability, and timeless aesthetics, the building integrates both modern functionality and traditional Indian heritage.</p>\r\n\r\n<p>What was the challenge?</p>\r\n\r\n<p>Humanising the Parliament landscape to align with the&nbsp;<strong>building&rsquo;s colour and texture</strong>&nbsp;is a sensitive and complex task, especially for a national symbol like the New Parliament Building.</p>\r\n\r\n<p>Strict adherence to the building&#39;s earthy, formal tones (like red sandstone, beige, or muted textures)</p>\r\n\r\n<p>It is technically challenging to&nbsp;<strong>landscape transformation</strong>, the goal was to create an environment that complements the building&#39;s grandeur while embracing ecological sensitivity and aesthetic harmony.</p>\r\n\r\n<p>Yuccabe Planters was entrusted with a pivotal role in enhancing the visual and environmental appeal of the building&#39;s outdoor and semi-covered spaces. Our objective was to&nbsp;<strong>design and manufacture customized planters</strong>&nbsp;that would seamlessly blend with the&nbsp;<strong>building&rsquo;s unique colour palette, materials, and architectural language.</strong></p>\r\n\r\n<p>We develop planter designs that aligned with the earthy tones, red sandstone fa&ccedil;ade, and the clean, angular geometry of the Parliament building.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Material &amp; Finish Customization:</strong></p>\r\n\r\n	<ul>\r\n		<li>\r\n		<p>Planters were crafted using hybrid-polymers and composites.<strong>High-grade FRP</strong>for strength and stability.</p>\r\n		</li>\r\n		<li>\r\n		<p>Finishes were customized in<strong>earthy terracotta, sandstone, and muted bronze textures</strong>, complementing the Parliament building&rsquo;s natural material palette.</p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n	<li>\r\n	<p><strong>Size &amp; Form Customization:</strong></p>\r\n\r\n	<ul>\r\n		<li>\r\n		<p>Designed&nbsp;<strong>various planter forms</strong>&mdash;tall, broad-based, and recessed models&mdash;to suit different zones including entry plazas, courtyards, corridors, and podium areas.</p>\r\n		</li>\r\n		<li>\r\n		<p>Sizes were tailored for&nbsp;<strong>specific native and ornamental plants</strong>, enhancing visual impact and plant health.</p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n	<li>\r\n	<p><strong>Visual Harmony:</strong>&nbsp;The planters acted as transitional elements between the built environment and green landscaping,&nbsp;<strong>amplifying the architectural intent</strong>&nbsp;and creating soft visual breaks.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>National Symbolism:</strong>&nbsp;Through the thoughtful selection of textures and colours, the planters helped&nbsp;<strong>honour India&rsquo;s cultural narrative</strong>&nbsp;while showcasing modern design precision.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Recognition:</strong>&nbsp;The aesthetic and functional contribution of Yuccabe Planters has been well acknowledged by project stakeholders, affirming our commitment to quality, customisation, and design excellence.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Yuccabe Planters is proud to have been part of this prestigious national project. Our ability to&nbsp;<strong>incorporate design with function</strong>&nbsp;and deliver&nbsp;<strong>custom solutions at scale</strong>&nbsp;reinforces our position as a trusted partner in high-impact architectural and landscape projects across India.</p>\r\n', 1, 1),
(5, 'projects/1779427100_testign3.jpg,projects/1779427100_testing1.jpg,projects/1779427100_testing22.jpg', 'Indira Gandhi International Airport T1', 'indira-gandhi-intermational-airport', 'Terminal Tranquility', '<h4>Indira Gandhi International Airport: Terminal 1</h4>\r\n\r\n<p>Client:</p>\r\n\r\n<h4>L&amp;T (direct); GMR Group / Delhi International Airport Limited</h4>\r\n\r\n<p>Location:</p>\r\n\r\n<h4>Indira Gandhi International Airport, Terminal 1D, New Delhi</h4>\r\n\r\n<p>Year of Completion:</p>\r\n\r\n<h4>2024</h4>\r\n\r\n<p>Terminal 1D at Indira Gandhi International Airport, Delhi, underwent a strategic enhancement to create a calming, modern, and globally aligned human experience. As part of this upgrade, to soften this space biophilic design principles were integrated, introducing greenery and natural elements to soften the space.</p>\r\n\r\n<h3>What was the objective?</h3>\r\n\r\n<p>To humanise and green the terminal interiors for a better travel experience.</p>\r\n\r\n<p>To use planters as design tools for demarcation, visual flow, and aesthetic depth.</p>\r\n\r\n<h3>The Yuccabe Planter Approach</h3>\r\n\r\n<p>We were given the opportunity to take over the project based on our expertise in custom planter solutions, ability to meet architectural specifications, and proven quality in high-traffic commercial environments.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Customised Planters</strong></p>\r\n\r\n	<ul>\r\n		<li>\r\n		<p>Size Customisation: Planters were tailored to fit specific spatial zones&mdash;from wide open areas to tight column surrounds and corner pockets.</p>\r\n		</li>\r\n		<li>\r\n		<p>Texture &amp; Finish: Special textures were developed to reflect the terminal&rsquo;s flooring material palette. Finishes were made in neutral stone textures to harmonise with the interior architecture.</p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n	<li>\r\n	<p><strong>Material Specification</strong></p>\r\n\r\n	<ul>\r\n		<li>\r\n		<p>All planters were made using hybrid polymers which are reinforced for strength and stability&mdash; thus proven to be lightweight, crack-resistant, and weatherproof.</p>\r\n		</li>\r\n		<li>\r\n		<p>UV-resistant and easy-to-clean surfaces ensured long-term durability with minimal maintenance.</p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p>Yuccabe Planters is proud to have contributed to the transformation of one of India&rsquo;s busiest airports. This project reflects our capability to deliver high-performance, aesthetically cohesive planter solutions at scale, in sync with architectural and functional demands of world-class infrastructure.</p>\r\n\r\n<p>We remain committed to enhancing spaces through intelligent greening &mdash; blending design and durability.</p>\r\n', 1, 2),
(6, 'projects/1779427324_mini1.jpg,projects/1779427324_mini2.jpg,projects/1779427324_mini3.jpg,projects/1779427324_mini4.jpg', 'Max Estate', 'max-estate', 'Minimalist Harmony', '<h4>Max Estates (All projects)</h4>\r\n\r\n<p>Client:</p>\r\n\r\n<h4>Max Estates 360</h4>\r\n\r\n<p>Location:</p>\r\n\r\n<h4>Okhla, Delhi(22-23&rsquo;); Noida sec -16A(2016), Max 360 Experience centre (25&rsquo;), Max Estates 128 (2024); MAX square sec135 Noida(23-24&rsquo;).</h4>\r\n\r\n<p>Year of Completion:</p>\r\n\r\n<h4>ongoing</h4>\r\n\r\n<h4>What was the objective?</h4>\r\n\r\n<p>Max Estates, known for their premium commercial and residential developments, approached Yuccabe Planters with a need for bespoke planter solutions. Their vision: to integrate planters seamlessly into the architectural language of their interiors and landscapes. This included:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Ensuring aesthetic harmony with the interior finishes and landscape materials.</p>\r\n	</li>\r\n	<li>\r\n	<p>Creating durable outdoor planters capable of withstanding harsh climate conditions.</p>\r\n	</li>\r\n	<li>\r\n	<p>Designing planters in specific sizes, shapes, and colors to fit designated spaces and complement furniture and finishes.</p>\r\n	</li>\r\n	<li>\r\n	<p>Blending modern minimalism with elements of natural elegance.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h4>The Yuccabe Planter Approach</h4>\r\n\r\n<p>Yuccabe&rsquo;s design and production team collaborated closely with Max Estates&#39; architects and landscape consultants throughout the developmental phases.</p>\r\n\r\n<p>We proposed what would fit best according to the architecture:</p>\r\n\r\n<p>- Sleek matte-finish planters in muted tones for corridors and common lounges.</p>\r\n\r\n<p>- Textured stone-look planters for patios and balconies.</p>\r\n\r\n<p>- Oversized contemporary pots for grand landscape entrances and central courtyards.</p>\r\n\r\n<p>Over 1200+ custom planters delivered within designated production timeline across all the projects.</p>\r\n\r\n<p>Coordinated logistics for phased delivery across different Max sites.</p>\r\n\r\n<p>The Impact</p>\r\n\r\n<ul>\r\n	<li>The planters became integral design elements in Max Estates&#39; interiors and landscape design.</li>\r\n	<li>Enhanced the biophilic appeal of both workspaces and living spaces.</li>\r\n	<li>Proved that durable, lightweight, and aesthetic planters can be made entirely in India, on a custom basis, without compromising on quality.</li>\r\n</ul>\r\n\r\n<p>We remain committed to enhancing spaces through intelligent greening &mdash; blending design and durability.</p>\r\n', 1, 3);

