(1, 'BAR', 'Bar', 'Bar', 1, 'bar', 'subsubcategories/1770718632.jpg', '35 Ltr Water Heater', '[\"subsubcategories/1773741255_1802.png\",\"subsubcategories/1773741255_2131.png\",\"subsubcategories/1773741255_4316.png\"]', 'subsubcategories/1770718632_breadcrumb.jpg', '<h3><strong>Bar Planters &ndash; Modern Rectangular Planters for Stylish Indoor &amp; Outdoor Spaces</strong></h3>\r\n\r\n<p><span style=\"font-size:16px\">The FRP Bar Planters feature a sleek, elongated rectangular design that brings a clean, contemporary look to any environment. Crafted for long-lasting durability and aesthetic appeal, these modern FRP planters are perfect for creating elegant linear plant arrangements along walls, corridors, balconies, and entrances.</span></p>\r\n\r\n<h3><strong>Customization Available:</strong></h3>\r\n\r\n<p><span style=\"font-size:16px\">Offered in a wide range of sizes and colors, allowing you to match any d&eacute;cor style and meet your spatial requirements effortlessly.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Best suited for:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Office lobbies</span></li>\r\n	<li><span style=\"font-size:16px\">Terraces &amp; patios</span></li>\r\n	<li><span style=\"font-size:16px\">Commercial spaces</span></li>\r\n	<li><span style=\"font-size:16px\">Caf&eacute;s &amp; resorts</span></li>\r\n	<li><span style=\"font-size:16px\">Modern home interiors</span></li>\r\n	<li><span style=\"font-size:16px\">Walkway styling &amp; green partitions</span></li>\r\n</ul>\r\n', '', 1, 1, 'Bar Planters - FRP Fibre Planterss', 'Modern rectangular FRP bar planters ideal for linear plant arrangements in indoor and outdoor spaces.', 'bar planters, rectangular frp planters, frp bar planter', '', NULL, '2026-05-25 11:33:00'),
(2, 'BEAD', 'Bead', 'Bead', 1, 'bead', 'subsubcategories/1770718767.jpg', 'Bead', '[\"subsubcategories\\/1770876040_4456.jpg\",\"subsubcategories\\/1770876040_8638.jpg\"]', 'subsubcategories/1770718767_breadcrumb.jpg', '<h2><strong>Bead Planters &ndash; Modern Vertical Bead Texture Planters in Cube &amp; Cylindrical Designs</strong></h2>\r\n\r\n<p><span style=\"font-size:16px\">The FRP Bead Planters feature a stylish vertical bead texture that adds depth, elegance, and a contemporary touch to any setting. Available in both cube and cylindrical shapes, these planters are crafted from high-quality FRP, ensuring superior durability, lightweight strength, and long-lasting weather resistance.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Customization Available:</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">Choose from a wide range of sizes and colors to perfectly complement your interior d&eacute;cor or landscape design theme.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Best Suitable For:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Luxury home interiors</span></li>\r\n	<li><span style=\"font-size:16px\">Hotel lobbies</span></li>\r\n	<li><span style=\"font-size:16px\">Balconies &amp; patios</span></li>\r\n	<li><span style=\"font-size:16px\">Corporate offices</span></li>\r\n	<li><span style=\"font-size:16px\">Outdoor lounges &amp; caf&eacute;s</span></li>\r\n	<li><span style=\"font-size:16px\">Modern residential spaces</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><img alt=\"\" src=\"https://yuccabeplanters.co.in/cms_forY/public/uploads/1774436723_69c3c173b1d5c.jpg\" style=\"height:237px; width:800px\" /></span></p>', NULL, 1, 1, 'Bead Planters - FRP Fibre Planters', 'Vertical bead textured FRP planters available in cube and cylindrical designs for modern spaces.', 'bead planters, textured frp planters, modern frp planters', NULL, NULL, '2026-03-25 18:05:57'),
(3, 'BEAD TRAY', 'BEAD TRAY', 'BEAD TRAY', 1, 'bead-tray', 'subsubcategories/1770876169.jpg', 'BEAD TRAY', '[\"subsubcategories\\/1770876169_5591.jpg\"]', 'subsubcategories/1770876169_breadcrumb.jpg', '<h4><span style=\"color:#000000\"><strong>FRP Bead Bar Planters &ndash; Premium Vertical Bead Design Planters</strong></span></h4>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">The FRP Bead Bar Planter features a sleek, elongated rectangular shape with an elegant vertical bead texture, making it perfect for adding structure and sophistication to contemporary environments.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Customization Available:</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Offered in multiple sizes and colors to match any interior or landscape theme effortlessly.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Best suited for:</span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hotel entrances</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Office corridors</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Balconies &amp; terraces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Caf&eacute;s &amp; outdoor patios</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Reception zones &amp; poolside decor</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Modern architectural spaces</span></span></li>\r\n</ul>', NULL, 1, 1, 'Bead Tray Planters - FRP Fibre Planters', 'Premium FRP bead tray planters with vertical texture for modern linear styling.', 'bead tray planter, frp tray planter, modern frp planters', NULL, NULL, '2026-04-06 17:26:41'),
(4, 'BOX TRA', 'BOX TRA', 'BOX TRA', 1, 'box-tra', 'subsubcategories/1770876286.jpg', 'BOX TRA', '[\"subsubcategories\\/1775111539_5156.jpg\"]', 'subsubcategories/1770876286_breadcrumb.jpg', '<h4><span style=\"color:#000000\"><strong>FRP BoxTra Planters &ndash; Modern Rectangular Planters</strong></span></h4>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">The FRP BoxTra Planter features a clean, smooth, and modern rectangular box design, making it ideal for stylish and structured green displays.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Customization Available:</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Choose from a wide range of sizes and colors to match subtle or bold d&eacute;cor themes.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Best suited for:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Balconies &amp; terraces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Patios &amp; caf&eacute;s</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Corporate offices</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hotel lobbies</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Walkways</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Modern home interiors</span></span></li>\r\n</ul>', NULL, 1, 1, 'BoxTra Planters - FRP Fibre Planters', 'Modern rectangular FRP box planters for balconies, offices and contemporary interiors.', 'box tra planter, rectangular frp planter, modern planters', NULL, NULL, '2026-04-06 17:26:55'),
(5, 'BTM-GRUV & BTM GRV TRAY', 'BTM-GRUV & BTM GRV TRAY', 'BTM-GRUV & BTM GRV TRAY', 1, 'btm-gruv-btm-grv-tray', 'subsubcategories/1770876497.jpg', 'BTM-GRUV & BTM GRV TRAY', '[\"subsubcategories\\/1770876497_8014.jpg\"]', 'subsubcategories/1770876497_breadcrumb.jpg', '<h4><span style=\"color:#000000\"><strong>BTM Gruv &amp; BTM GRV Tray Planters &ndash; Modern Groove Design Planters</strong></span></h4>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">FRP BTM Gruv &amp; BTM GRV Tray Planters feature a sleek rectangular design with horizontal groove accents for a refined modern look.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Customization Available:</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Available in a wide range of sizes and colors to perfectly match balconies, gardens, and commercial spaces.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Best suited for:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Balconies &amp; patios</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Window-front areas</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Villa entrances</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Office corridors</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Terraces &amp; outdoor walkways</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Space dividers &amp; fa&ccedil;ade planters</span></span></li>\r\n</ul>', NULL, 1, 1, 'BTM Gruv Planters - FRP Fibre Planters', 'Grooved FRP tray planters with modern horizontal detailing for balconies and walkways.', 'btm gruv planter, groove frp planters, frp tray planters', NULL, NULL, '2026-04-06 17:27:31'),
(6, 'CHAJ & CHAJ TRA', 'CHAJ & CHAJ TRA', 'CHAJ & CHAJ TRA', 1, 'chaj-chaj-tra', 'subsubcategories/1770876534.jpg', 'CHAJ & CHAJ TRA', '[\"subsubcategories\\/1770876534_3531.jpg\"]', 'subsubcategories/1770876534_breadcrumb.jpg', '<h4><span style=\"color:#000000\"><strong>Chaj &amp; Chaj Tra Models | Premium BTM Gruv Design</strong></span></h4>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">The FRP Chaj &amp; Chaj Tra Planters feature a unique curved structure crafted in the elegant BTM Gruv design. These premium FRP planters add sculpted appeal to luxury interiors and modern landscapes.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Shape Specialization:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Chaj: Wide top with inward-curved silhouette</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Chaj Tra: Sleek elongated variation for linear arrangements</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Customization Options:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Fully customizable sizes</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Available in matte, gloss, metallic, stone &amp; textured finishes</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Best Used For:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Luxury hotel lobbies</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Corporate interiors</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Balconies &amp; patios</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Caf&eacute; d&eacute;cor</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Walkways &amp; entrance highlights</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Indoor decorative corners</span></span></li>\r\n</ul>', NULL, 1, 1, 'Chaj Planters - FRP Fibre Planters', 'Curved premium FRP planters with sculpted BTM Gruv design for luxury interiors.', 'chaj planter, curved frp planter, designer frp planters', NULL, NULL, '2026-04-06 17:28:18'),
