(9, 'CURVITRA', 'Curvitra', 'Curvitra', 1, 'curvitra', 'subsubcategories/1770877147.jpg', 'Curvitra', '[\"subsubcategories\\/1770877147_2715.jpg\",\"subsubcategories\\/1770877147_1641.jpg\"]', 'subsubcategories/1770877147_breadcrumb.jpg', '<h3><span style=\"color:#000000\"><strong>Curvitra Planters</strong></span></h3>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">The FRP Curvitra Planter stands out with its curved, concave silhouette&mdash;blending modern elegance with smooth sculpted contours. Crafted from premium FRP, it offers durability, weather resistance, and a refined premium finish.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Shape Specialization:</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Inward-curved sculpted profile that adds fluidity and balance, ideal for showcasing tall ornamental plants.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Customization:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Available in customizable sizes for corners, hallways &amp; open spaces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Offered in matte, glossy, metallic &amp; custom colors</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Best Used For:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Luxury home interiors &amp; foyers</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hotel lobbies &amp; premium lounges</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Corporate offices &amp; reception areas</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Balconies, terraces &amp; walkways</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Modern spaces require a sculptural focal point</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><img alt=\"\" src=\"https://yuccabeplanters.co.in/cms_forY/public/uploads/1774437150_69c3c31e19409.jpg\" style=\"height:148px; width:500px\" /></span></span></p>', NULL, 1, 1, 'Curvitra Planters - FRP Fibre Planters', 'Elegant curved FRP planters with sculpted concave profile for premium spaces.', 'curvitra planter, curved frp planter, designer planters', NULL, NULL, '2026-03-25 18:13:53'),
(10, 'GK TRAY', NULL, NULL, 1, 'gk-tray', 'subsubcategories/1770877186.png', NULL, '[\"subsubcategories\\/1770877186_7511.png\"]', 'subsubcategories/1770877186_breadcrumb.png', '<h4><strong>GK Tray Planters</strong></h4><p>The FRP GK Tray Planter features a sleek, elongated tray-style design that provides a modern, clean aesthetic for indoor and outdoor spaces. Its wide, shallow form is ideal for linear plant arrangements.</p><p><strong>Shape Specialization:</strong></p><p>Minimalistic rectangular tray suitable for succulents, low-height plants, and decorative layering.</p><p><strong>Customization Options:</strong></p><ul><li>Customizable sizes for windowsills, ledges, partitions &amp; balcony railings</li><li>Available in matte, glossy &amp; premium finishes</li></ul><p><strong>Best Used For:</strong></p><ul><li>Office workspaces &amp; reception counters</li><li>Hotel lobbies, café interiors &amp; retail stores</li><li>Home décor—living rooms, dining consoles &amp; window spaces</li><li>Terrace gardens, patios &amp; pathways</li><li>Linear styling &amp; contemporary décor</li></ul>', NULL, 1, 1, 'GK Tray Planters - FRP Fibre Planters', 'Minimal tray-style FRP planters for linear plant arrangements and décor.', 'gk tray planter, frp tray planter, modern trays', NULL, NULL, '2026-02-12 13:19:46'),
