(12, 'HLIN TRAY', 'HLIN TRAY', 'HLIN TRAY', 1, 'hlin-tray', 'subsubcategories/1770878044.png', NULL, '[\"subsubcategories\\/1770878044_5234.png\",\"subsubcategories\\/1770878044_9374.jpg\"]', 'subsubcategories/1770878044_breadcrumb.png', '<h3><span style=\"color:#000000\"><strong>HLIN Tray Planters</strong></span></h3>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">The FRP HLIN Tray Planters offer a sleek elongated rectangular profile ideal for creating continuous green borders and modern linear arrangements.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Shape Specialization:</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Shallow-to-medium depth tray ideal for ornamental grasses, succulents &amp; decorative plants.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Customization Options:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Fully customizable in sizes, colors &amp; finishes</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Suitable for residential, commercial &amp; luxury setups</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Best Used For:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Balcony &amp; terrace railings</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Window sills &amp; entrance spaces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Office partitions</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hotel lobbies &amp; caf&eacute;s</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Walkways &amp; corridors</