(13, 'SELVET', 'Selvet', 'Selvet', 1, 'selvet', 'subsubcategories/1770878108.jpg', 'Selvet', '[\"subsubcategories\\/1770878108_8252.jpg\"]', 'subsubcategories/1770878108_breadcrumb.jpg', '<h4><strong>Sevelt FRP Planters</strong></h4>\r\n\r\n<p>The FRP Sevelt Planters feature a slender, softly curved silhouette that adds elegance and height to modern indoor and outdoor environments.</p>\r\n\r\n<p><strong>Shape Specialization:</strong></p>\r\n\r\n<p>Tall, streamlined and gently tapered form ideal for showcasing statement greens.</p>\r\n\r\n<p><strong>Customization Options:</strong></p>\r\n\r\n<ul>\r\n	<li>Available in various sizes &amp; finishes</li>\r\n	<li>Matte, gloss, textured &amp; metallic tones</li>\r\n</ul>\r\n\r\n<p><strong>Best Used For:</strong></p>\r\n\r\n<ul>\r\n	<li>Entrances &amp; foyers</li>\r\n	<li>Office cabins &amp; reception zones</li>\r\n	<li>Hotel lobbies &amp; premium lounges</li>\r\n	<li>Balconies &amp; corridors</li>\r\n	<li>Retail spaces &amp; modern living rooms</li>\r\n</ul>', NULL, 1, 1, 'Sevelt Planters - FRP Fibre Planters', 'Tall and slender FRP planters ideal for entrances and premium interiors.', 'sevelt planter, tall frp planter, modern planters', NULL, NULL, '2026-03-25 16:44:38'),
(14, 'TILE TRA', 'TILE TRA', 'TILE TRA', 1, 'tile-tra', 'subsubcategories/1774432020.png', NULL, '[\"subsubcategories\\/1774432121_8552.png\",\"subsubcategories\\/1774432121_9460.png\",\"subsubcategories\\/1774432121_7174.jpg\"]', 'subsubcategories/1774432020_breadcrumb.jpg', '<h4>Tile Tray FRP Planters</h4>\r\n\r\n<p>The FRP Tile Tray Planters feature a flat, tile-inspired rectangular profile designed for modern and minimal d&eacute;cor themes. Built with high-quality FRP, they ensure long-lasting strength and refined aesthetics.</p>\r\n\r\n<p>Shape Specialization:</p>\r\n\r\n<p>Low-height, wide tray-style design ideal for succulents, bonsai, flowering plants &amp; clustered arrangements.</p>\r\n\r\n<p>Customization Options:</p>\r\n\r\n<ul>\r\n	<li>Sizes from compact ledge trays to large rectangular trays</li>\r\n	<li>Available in matte, gloss, metallic, textured &amp; concrete-style finishes</li>\r\n</ul>\r\n\r\n<p>Best Used For:</p>\r\n\r\n<ul>\r\n	<li>Balconies, terraces &amp; windowsills</li>\r\n	<li>Center tables, console tables &amp; reception counters</li>\r\n	<li>Hotel lounges &amp; caf&eacute;s</li>\r\n	<li>Pathway borders &amp; wall-top landscaping</li>\r\n	<li>Home d&eacute;cor &amp; office workstations</li>\r\n</ul>', NULL, 1, 1, 'Tile Tray Planters - FRP Fibre Planters', 'Low-height tile-style FRP tray planters for minimal and modern décor.', 'tile tray planter, frp tray planter, modern planters', NULL, NULL, '2026-03-25 16:48:41'),
(15, 'TK', NULL, NULL, 1, 'tk', 'subsubcategories/1770878494.jpg', NULL, '[\"subsubcategories\\/1770878494_3243.jpg\",\"subsubcategories\\/1770878494_2557.jpg\"]', 'subsubcategories/1770878494_breadcrumb.jpg', '<h4><strong>TK FRP Planters</strong></h4><p>The FRP TK Planters feature a tall, sleek silhouette that adds structure and vertical elegance to any space. Crafted from premium FRP, they offer exceptional durability and modern styling.</p><p><strong>Shape Specialization:</strong></p><p>Tall, vertical form ideal for statement plants, corner spaces &amp; modern entrances.</p><p><strong>Customization Options:</strong></p><ul><li>Available in multiple sizes—from compact tall units to grand floor-standing models</li><li>Finishes include matte, gloss, metallic, textured &amp; dual-tone</li></ul><p><strong>Best Used For:</strong></p><ul><li>Hotel lobbies &amp; entrances</li><li>Corporate offices &amp; reception areas</li><li>Balconies, terraces &amp; patios</li><li>Restaurants, cafés &amp; showrooms</li><li>Living rooms, foyers &amp; hallways</li><li>Outdoor landscaping requiring vertical elements</li></ul>', NULL, 1, 1, 'TK Planters - FRP Fibre Planters', 'Tall vertical FRP planters designed for entrances and statement greenery.', 'tk planter, tall frp planter, vertical planters', NULL, NULL, '2026-02-12 13:41:34'),
(16, 'TOP-GRUV-TRA', NULL, NULL, 1, 'top-gruv-tra', 'subsubcategories/1770878532.jpg', NULL, '[\"subsubcategories\\/1770878532_9099.jpg\"]', 'subsubcategories/1770878532_breadcrumb.jpg', '<h4><strong>Top Gruv Tray Planters</strong></h4><p>The FRP Top Gruv Tray Planters feature an elongated tray design enhanced with refined top-grooved detailing, adding a modern and stylish appearance to any setting.</p><p><strong>Shape Specialization:</strong></p><ul><li>Elongated rectangular form ideal for linear plants</li><li>Top-groove detailing for an elevated aesthetic</li><li>Perfect for neat, continuous green borders</li></ul><p><strong>Customization Options:</strong></p><ul><li>Custom sizes for tabletops, railing spaces &amp; large outdoor layouts</li><li>Available in matte, gloss, metallic, stone finish &amp; textured shades</li></ul><p><strong>Best Used For:</strong></p><ul><li>Balconies &amp; terraces</li><li>Office corridors &amp; reception areas</li><li>Hotels, cafés &amp; restaurants</li><li>Walkways, patios &amp; garden boundaries</li><li>Window ledges &amp; partition styling</li></ul>', NULL, 1, 1, 'Top Gruv Tray Planters - FRP Fibre Planters', 'Top-grooved FRP tray planters for clean and modern linear landscaping.', 'top gruv tray, frp tray planter, groove planters', NULL, NULL, '2026-02-12 13:42:12'),
(17, 'UASA TRAY', NULL, NULL, 1, 'uasa-tray', 'subsubcategories/1770879082.png', NULL, '[\"subsubcategories\\/1770879082_7402.jpg\",\"subsubcategories\\/1770879082_7671.jpg\"]', 'subsubcategories/1770879082_breadcrumb.png', '<h4><strong>UASA Tray Planters</strong></h4><p>The FRP UASA Tray Planters feature a low-height rectangular tray design that brings clean minimalism and modern structure to any décor environment.</p><p><strong>Shape Specialization:</strong></p><p>Wide, low-profile tray suitable for succulents, herbs, small plants &amp; decorative arrangements.</p><p><strong>Customization Options:</strong></p><ul><li>Available in various compact to large tray sizes</li><li>Matte, gloss, metallic, stone-finish &amp; custom designer shades</li></ul><p><strong>Best Used For:</strong></p><ul><li>Tabletops &amp; reception counters</li><li>Balconies, window ledges &amp; terrace railings</li><li>Hotel lobbies &amp; cafés</li><li>Living rooms, hallways &amp; console setups</li><li>Outdoor seating areas &amp; garden shelves</li></ul>', NULL, 1, 1, 'UASA Tray Planters - FRP Fibre Planters', 'Low-profile FRP tray planters for tabletops, ledges and minimal décor.', 'uasa tray planter, frp tray planter, modern planters', NULL, NULL, '2026-02-12 13:51:22'),
(18, 'UGK', 'UGK', 'UGK', 1, 'ugk', 'subsubcategories/1770879163.png', 'UGK', '[\"subsubcategories\\/1770879163_3004.jpg\",\"subsubcategories\\/1770879163_1215.jpg\"]', 'subsubcategories/1770879163_breadcrumb.png', '<h3><span style=\"color:#000000\"><strong>UGK FRP Planters</strong></span></h3>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Bold geometric FRP planters crafted for premium modern styling.</span></span></p>\r\n\r\n<h4><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Shape Specialization:</strong></span></span></h4>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Angular geometric form suited for medium to tall plants.</span></span></p>\r\n\r\n<h4><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Customization Options:</strong></span></span></h4>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Available in various finishes.</span></span></p>\r\n\r\n<h4><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Best Used For:</strong></span></span></h4>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hotel entrances</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Home interiors</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Outdoor lounges</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><img alt=\"\" src=\"https://yuccabeplanters.co.in/cms_forY/public/uploads/1774437550_69c3c4ae03a32.jpg\" style=\"height:207px; width:700px\" /></span></span></p>', NULL, 1, 1, 'UGK Planters - FRP Fibre Planters', 'Geometric FRP planters with bold angular styling for modern interiors.', 'ugk planter, geometric frp planter, designer planters', NULL, NULL, '2026-03-25 18:21:42'),
(19, 'VIPU & VIPU TRAY', NULL, NULL, 1, 'vipu-vipu-tray', 'subsubcategories/1770879866.jpg', NULL, '[\"subsubcategories\\/1770879866_3705.jpg\"]', 'subsubcategories/1770879866_breadcrumb.jpg', '<h4><strong>VIPU FRP Planters</strong></h4><p>The FRP VIPU Planters feature an elegant, gently tapered design that adds sculptural refinement to any space. Crafted from high-quality FRP, they provide durability, style, and long-lasting performance.</p><p><strong>Shape Specialization:</strong></p><p>Smooth, curved taper ideal for medium to tall ornamental plants, offering a soft and modern aesthetic.</p><p><strong>Customization Options:</strong></p><ul><li>Available in multiple sizes—from compact pieces to large statement planters</li><li>Color options include matte, gloss, metallic, stone texture &amp; fully custom shades</li></ul><p><strong>Best Used For:</strong></p><ul><li>Hotel lobbies &amp; reception areas</li><li>Corporate offices &amp; conference rooms</li><li>Balconies, terraces &amp; patios</li><li>Cafés, restaurants &amp; showroom interiors</li><li>Living rooms, foyers &amp; hallways</li></ul>', NULL, 1, 1, 'VIPU Planters - FRP Fibre Planters', 'Elegant tapered FRP planters for premium interiors and outdoor spaces.', 'vipu planter, tapered frp planter, modern planters', NULL, NULL, '2026-02-12 14:04:26'),
(20, 'ALPHA GH', NULL, NULL, 2, 'alpha-gh', 'subsubcategories/1770880569.jpg', NULL, '[\"subsubcategories\\/1770880569_1630.jpg\"]', 'subsubcategories/1770880569_breadcrumb.jpg', '<h3><strong>Alpha GH FRP Planters</strong></h3><p>The FRP Alpha GH Planters feature an elegant bowl-inspired design with a gently rounded silhouette, adding softness and sophistication to any décor space. Made from premium Fiber Reinforced Plastic (FRP), these planters are durable, lightweight, weather-resistant, and ideal for both indoor and outdoor styling.</p><p><strong>Shape Specialization</strong></p><p>The Alpha GH planter stands out due to its:</p><ul><li>Smooth, bowl-shaped form that enhances plant visibility and creates a striking centerpiece</li><li>Gracefully curved edges, offering a modern yet timeless look</li><li>Wide opening, making it perfect for lush plants, floral arrangements, and decorative setups</li></ul><p>Its bowl geometry brings balance and elegance to any residential or commercial environment.</p><p><strong>Customization Options</strong></p><p>The Alpha GH Planters can be customized in:</p><ul><li>Multiple sizes – from small decorative bowls to large statement planters</li><li>Various finishes and colors – matte, gloss, metallic, stone textures, and custom shades</li></ul><p>This ensures seamless integration with minimal, luxury, contemporary, or nature-inspired décor themes.</p><p><strong>Best Used For</strong></p><p>The Alpha GH FRP Planters are ideal for:</p><ul><li>Hotel lobbies, premium receptions, and luxury lounges</li><li>Living rooms, foyer areas, balconies, and terraces</li><li>Restaurants, cafés, and boutique interiors</li><li>Garden landscapes, poolside areas, and outdoor seating zones</li><li>Office entrances, cabins, and collaborative spaces</li></ul><p>With its refined bowl-shaped design and premium finish, the Alpha GH planter beautifully elevates greenery, making it a perfect centerpiece for modern interiors and sophisticated landscapes.</p>', NULL, 1, 1, 'Alpha GH Bowl Planters - FRP Fibre Collection', 'Premium bowl-shaped FRP planters with elegant curves for luxury indoor and outdoor spaces.', 'alpha gh planter, frp bowl planter, designer bowl planters', NULL, NULL, '2026-02-12 14:16:09'),
(21, 'APPL', 'APPL', 'APPL', 2, 'appl', 'subsubcategories/1770880759.jpg', 'APPL', '[\"subsubcategories\\/1770880759_8546.jpg\",\"subsubcategories\\/1770880759_4496.jpg\"]', 'subsubcategories/1770880759_breadcrumb.jpg', '<h3><strong>APPL FRP Planters &ndash; Premium Cube &amp; Cylindrical Designs for Modern Spaces</strong></h3>\r\n\r\n<p><span style=\"font-size:16px\">The APPL Series showcases high-quality FRP (Fiberglass Reinforced Plastic) planters crafted in elegant cube and cylindrical shapes, perfect for adding a modern, structured look to any indoor or outdoor setting. Designed for durability, lightweight handling, and long-lasting performance, these planters bring style and functionality together.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Shape Specialization</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Cube FRP Planters</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Ideal for creating a bold, structured, and contemporary aesthetic</span></li>\r\n	<li><span style=\"font-size:16px\">Clean lines and sharp geometry make them perfect for corners, entryways, and corporate spaces</span></li>\r\n	<li><span style=\"font-size:16px\">Best suited for tall plants, palms, bamboo, or ornamental greens</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Cylindrical FRP Planters</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Smooth curves offer a soft, timeless appeal</span></li>\r\n	<li><span style=\"font-size:16px\">Perfect for lobbies, balconies, patios, and living rooms</span></li>\r\n	<li><span style=\"font-size:16px\">Complements flowering plants, indoor shrubs, or statement foliage</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Customization Options</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">APPL FRP planters are fully customizable in:</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Sizes: Small to oversized, depending on plant and space requirements</span></li>\r\n	<li><span style=\"font-size:16px\">Colors: Matte, gloss, metallic, textured and custom shade options</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Best Usage Recommendations</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">Use APPL FRP planters effectively in:</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Modern homes &amp; luxury interiors</span></li>\r\n	<li><span style=\"font-size:16px\">Office reception areas and corporate environments</span></li>\r\n	<li><span style=\"font-size:16px\">Hotel lobbies, caf&eacute;s, and high-end retail spaces</span></li>\r\n	<li><span style=\"font-size:16px\">Balconies, terraces, gardens, and patios</span></li>\r\n	<li><span style=\"font-size:16px\">Pathways, entrance zones, and landscape projects</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Why Choose APPL FRP Planters?</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Lightweight yet extremely sturdy</span></li>\r\n	<li><span style=\"font-size:16px\">Weather-resistant and corrosion-free</span></li>\r\n	<li><span style=\"font-size:16px\">Easy to move, maintain, and clean</span></li>\r\n	<li><span style=\"font-size:16px\">Long-lasting colors and premium finish</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">Enhance your d&eacute;cor with the APPL FRP Planter Collection&mdash;where modern shapes, customization, and superior craftsmanship come together.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><img alt=\"\" src=\"https://yuccabeplanters.co.in/cms_forY/public/uploads/1774437820_69c3c5bc29143.jpg\" style=\"height:207px; width:700px\" /></span></p>', NULL, 1, 1, 'APPL FRP Planters - Bowls & Balls Collection', 'Modern cube and cylindrical FRP planters for homes, offices and luxury interiors.', 'appl planter, cube frp planter, cylindrical frp planter', NULL, NULL, '2026-03-25 18:24:02'),
(22, 'ASA', 'ASA', 'ASA', 2, 'asa', 'subsubcategories/1770881027.jpg', NULL, '[\"subsubcategories\\/1770881027_4488.jpg\",\"subsubcategories\\/1770881027_6791.jpg\",\"subsubcategories\\/1770881027_1814.jpg\"]', 'subsubcategories/1770881027_breadcrumb.jpg', '<h3><span style=\"color:#000000\"><strong>ASA FRP Planters &ndash; Stylish Cube &amp; Cylindrical Designs for Modern D&eacute;cor</strong></span></h3>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">The ASA Series features premium FRP (Fiberglass Reinforced Plastic) planters crafted in elegant cube and cylindrical shapes, designed to elevate any residential, commercial, or landscape setting. Known for their durability, smooth finish, and contemporary appeal, ASA planters offer the perfect blend of style and strength.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Shape Specialization</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Cube FRP Planters &ndash; Bold &amp; Structured</span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Sharp, clean edges for a modern architectural look</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Perfect for highlighting entryways, pathways, and minimalistic interiors</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Ideal for tall plants like areca palms, bamboo, dracaena, or decorative greens</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Cylindrical FRP Planters &ndash; Elegant &amp; Versatile</span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Smooth round contours that soften the overall d&eacute;cor</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Complements reception areas, balconies, gardens, and living rooms</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Best suited for shrubs, flowering plants, indoor palms, and ornamental foliage</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Customization Available</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">ASA FRP planters can be fully customized to match your space and design needs:</span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Sizes: From compact to large statement pieces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Colors: Gloss, matte, textured, metallic, or any custom shade</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">This flexibility makes ASA planters perfect for designers, architects, and homeowners looking for personalized d&eacute;cor solutions.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Where ASA Planters Work Best</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Use cube and cylindrical ASA FRP planters effectively in:</span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Luxury homes &amp; premium interior spaces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Corporate offices, waiting areas, and reception lobbies</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Hotels, resorts, caf&eacute;s, and boutique stores</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Outdoor patios, terraces, gardens, and poolside spaces</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Walkways, building entrances, and landscaping projects</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><strong>Why Choose ASA FRP Planters?</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Lightweight yet highly durable</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Weather-resistant &amp; corrosion-free</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Easy to maintain and move</span></span></li>\r\n	<li><span style=\"color:#000000\"><span style=\"font-size:16px\">Long-lasting finish with premium aesthetics</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\">Enhance your interiors and landscapes with ASA FRP Planters&mdash;crafted to bring sophistication, structure, and style to any environment.</span></span></p>\r\n\r\n<p><span style=\"color:#000000\"><span style=\"font-size:16px\"><img alt=\"\" src=\"https://yuccabeplanters.co.in/cms_forY/public/uploads/1774437903_69c3c60fdfd24.jpg\" style=\"height:207px; width:700px\" /></span></span></p>', NULL, 1, 1, 'ASA FRP Planters - Bowls & Balls Collection', 'Stylish cube and cylindrical FRP planters for modern residential and commercial spaces.', 'asa planter, frp cube planter, modern frp planters', NULL, NULL, '2026-03-25 18:25:15');
INSERT INTO `sub_sub_categories` (`id`, `name`, `bread_heading`, `bread_subheading`, `subcategory_id`, `slug`, `image`, `alt`, `multi_images`, `breadimage`, `description`, `long_desc`, `sort`, `status`, `metatag`, `metadescription`, `metakeywords`, `metatags`, `created_at`, `updated_at`) VALUES
(23, 'ASA KTR', 'ASA KTR', 'ASA KTR', 2, 'asa-ktr', 'subsubcategories/1770881096.jpg', 'ASA KTR', '[\"subsubcategories\\/1770881096_6539.jpg\"]', 'subsubcategories/1770881096_breadcrumb.jpg', '<h3><strong>ASA KTR FRP Planters &ndash; Premium Cube &amp; Cylindrical Designs for Modern Spaces</strong></h3>\r\n\r\n<p><span style=\"font-size:16px\">The ASA KTR Series brings a refined collection of FRP (Fiberglass Reinforced Plastic) planters available in cube and cylindrical shapes, crafted to enhance both indoor and outdoor environments. Designed with clean lines, smooth finishes, and long-lasting durability, ASA KTR planters are perfect for contemporary d&eacute;cor styles.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Shape Specialization</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">Cube FRP Planters &ndash; Minimalistic &amp; Architectural</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Defined edges that give a bold, structured look</span></li>\r\n	<li><span style=\"font-size:16px\">Ideal for modern interiors, commercial lobbies, corridors, and outdoor pathways</span></li>\r\n	<li><span style=\"font-size:16px\">Works beautifully with tall plants like ficus, bamboo, dracaena, and indoor palms</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">Cylindrical FRP Planters &ndash; Sleek &amp; Versatile</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Smooth, rounded silhouette that complements any d&eacute;cor theme</span></li>\r\n	<li><span style=\"font-size:16px\">Perfect for reception areas, balconies, gardens, lounges, and hotel spaces</span></li>\r\n	<li><span style=\"font-size:16px\">Suitable for flowering plants, ornamental greens, succulents, and shrubs</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Customization Available</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">ASA KTR planters offer full customization options, making them ideal for designers and premium projects:</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Sizes: Multiple height and width options, including large statement pieces</span></li>\r\n	<li><span style=\"font-size:16px\">Colors: Matte, gloss, textured, metallic, natural tones, or custom shades matching project themes</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">This ensures each planter perfectly aligns with your interior or landscape design vision.</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Where ASA KTR Planters Can Be Used Effectively</span></p>\r\n\r\n<p><span style=\"font-size:16px\">Maximize the beauty and functionality of ASA KTR planters in:</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Luxury homes &amp; high-end interior d&eacute;cor</span></li>\r\n	<li><span style=\"font-size:16px\">Corporate offices, reception zones, and meeting rooms</span></li>\r\n	<li><span style=\"font-size:16px\">Hotels, restaurants, caf&eacute;s, and boutique spaces</span></li>\r\n	<li><span style=\"font-size:16px\">Balcony gardens, terraces, courtyards, and patios</span></li>\r\n	<li><span style=\"font-size:16px\">Building entrances, pathways, and landscaping installations</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Why Choose ASA KTR FRP Planters?</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Lightweight yet strong &amp; impact-resistant</span></li>\r\n	<li><span style=\"font-size:16px\">Weatherproof and corrosion-free</span></li>\r\n	<li><span style=\"font-size:16px\">Suitable for indoor and outdoor use</span></li>\r\n	<li><span style=\"font-size:16px\">Easy to clean, move, and maintain</span></li>\r\n	<li><span style=\"font-size:16px\">Long-lasting premium finish</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">Enhance your d&eacute;cor with ASA KTR FRP Planters&mdash;a perfect blend of style, functionality, and contemporary aesthetics for any space.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><img alt=\"\" src=\"https://yuccabeplanters.co.in/cms_forY/public/uploads/1774437989_69c3c6653e918.jpg\" style=\"height:207px; width:700px\" /></span></p>', NULL, 1, 1, 'ASA KTR FRP Planters - Bowls & Balls Collection', 'Premium customizable FRP planters in cube and cylindrical forms.', 'asa ktr planter, frp designer planters, modern frp planters', NULL, NULL, '2026-03-25 18:26:38'),
(24, 'KTR', 'KTR', 'KTR', 2, 'ktr', 'subsubcategories/1770881336.jpg', 'KTR', '[\"subsubcategories\\/1770881336_1946.jpg\",\"subsubcategories\\/1770881336_9931.jpg\"]', 'subsubcategories/1770881336_breadcrumb.jpg', '<h3><strong>KTR FRP Planters &ndash; Elegant Bowls &amp; Curved Bowl Shapes for Modern Landscaping</strong></h3>\r\n\r\n<p><span style=\"font-size:16px\">The KTR Series offers beautifully crafted FRP (Fiberglass Reinforced Plastic) bowl-shaped planters, designed to add softness, style, and visual balance to any space. Known for their wide, rounded form and seamless finish, KTR planters bring a contemporary touch to interiors, gardens, and architectural landscapes.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Shape Specialization</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">Bowl &amp; Deep-Bowl Design</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Smooth, curved structure that brings a premium aesthetic to both indoor and outdoor settings</span></li>\r\n	<li><span style=\"font-size:16px\">Broad top opening ideal for showcasing lush, spreading plants</span></li>\r\n	<li><span style=\"font-size:16px\">Rounded profile helps create a calming, organic visual appeal</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Perfect for use as:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Statement centerpieces</span></li>\r\n	<li><span style=\"font-size:16px\">Accent planters in corners, patios, entrances</span></li>\r\n	<li><span style=\"font-size:16px\">Decorative additions in minimalist or luxury settings</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Customization Options</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">The KTR planter range is fully customizable to match your design theme:</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Sizes: Multiple diameters and depths, from compact bowls to large landscape planters</span></li>\r\n	<li><span style=\"font-size:16px\">Colors: Matte, gloss, textured, metallic, pastel tones, or custom shades as per project requirements</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">This flexibility makes KTR planters suitable for residential, commercial, and large-scale landscape installations.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Ideal Usage Areas</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\">KTR FRP planters work effectively in:</span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Living rooms, foyers, hotel lobbies, and premium indoor setups</span></li>\r\n	<li><span style=\"font-size:16px\">Terraces, balconies, waterbody edges, and zen gardens</span></li>\r\n	<li><span style=\"font-size:16px\">Resorts, restaurants, caf&eacute;s, and open courtyards</span></li>\r\n	<li><span style=\"font-size:16px\">Landscape projects such as walkways, pool areas, and garden pockets</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">Their wide bowl shape enhances plant spread and creates a luxurious d&eacute;cor statement.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Why Choose KTR FRP Planters?</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Lightweight yet structurally strong</span></li>\r\n	<li><span style=\"font-size:16px\">UV-resistant, weatherproof, and corrosion-free</span></li>\r\n	<li><span style=\"font-size:16px\">Ideal for both indoor and outdoor d&eacute;cor</span></li>\r\n	<li><span style=\"font-size:16px\">Low maintenance and long-lasting finish</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">Add style and sophistication to your space with KTR FRP Bowl Planters, perfectly designed to complement modern architectural and landscape aesthetics.</span></p>\r\n\r\n<p><span style=\"font-size:16px\"><img alt=\"\" src=\"https://yuccabeplanters.co.in/cms_forY/public/uploads/1774438080_69c3c6c03f405.jpg\" style=\"height:207px; width:700px\" /